{
  "tasks": [
    {
      "task_id": "T01",
      "title": "2026年各月任务数量统计",
      "business_question": "统计2026年每个月创建的任务数量，并按月份升序排列。",
      "priority": "P0",
      "priority_reason": "删除此任务将无法回答核心业务目标“统计2026年每个月创建的任务数量”，也无法支持相关决策。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "derive",
          "params": {
            "function": "extract_year",
            "field": "field_0001",
            "alias": "year_2026_check"
          }
        },
        {
          "step_id": "S02",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "year_2026_check",
                "operator": "eq",
                "value": 2026
              }
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "derive",
          "params": {
            "function": "extract_month",
            "field": "field_0001",
            "alias": "month_value"
          }
        },
        {
          "step_id": "S04",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "task_count"
              }
            ],
            "dimensions": [
              "month_value"
            ]
          }
        },
        {
          "step_id": "S05",
          "operation": "sort",
          "params": {
            "field": "month_value",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
